export const ARCHIVE_DOCUMENTS = [{"id":"leg_kyi","kind":"legend","year":482,"place":"Київ","language":"old_east_slavic","title":"Кий, Щек, Хорив і Либідь","original":"И бяху 3 братья: единому имя Кий, а другому Щекъ, а третьему Хоривъ, и сестра ихъ Лыбедь.","translation":"І було три брати: одному ім'я Кий, другому Щек, третьому Хорив, і сестра їхня Либідь.","fidelity":"historical","sources":["PVL, undated introduction (founding legend of Kyiv)"]},{"id":"leg_andrew","kind":"legend","year":483,"place":"Київ","language":"old_east_slavic","title":"Апостол Андрій на київських горах","original":"Видите ли горы сия? яко на сихъ горахъ восияеть благодать Божья; имать градъ великъ быти","translation":"Чи бачите гори ці? На цих горах засяє благодать Божа; бути тут великому місту.","fidelity":"historical","sources":["PVL, undated introduction (legend of the Apostle Andrew on the Kyiv hills)"]},{"id":"doc_treaty_911","kind":"document","year":911,"place":"Київ","language":"old_east_slavic","title":"Договір Олега з Візантією","original":"Мы от рода рускаго, Карлы, Инегелдъ, Фарлофъ, Веремудъ, Рулавъ, Гуды, Руалдъ, Карнъ, Фрелавъ, Руаръ, Актеву, Труанъ, Лидулъ, Фостъ, Стемидъ, иже послани от Олга, великого князя рускаго","translation":"Ми з роду руського — Карл, Інегелд, Фарлоф, Веремуд, Рулав, Гуди, Руалд, Карн, Фрелав, Руар, Актеву, Труан, Лідул, Фост, Стемид, — послані від Олега, великого князя руського.","fidelity":"historical","sources":["PVL s.a. 6420 (912), treaty of Oleh with Byzantium (Laurentian copy; spelling regularised)"]},{"id":"leg_olha_946","kind":"legend","year":946,"place":"Іскоростень","language":"old_east_slavic","title":"Помста Ольги","original":"Дайте ми от двора по 3 голуби да по 3 воробьи","translation":"Дайте мені від кожного двору по три голуби й по три горобці.","fidelity":"plausible","sources":["PVL s.a. 6454 (946), Olha's revenge on Iskorosten (spelling regularised)"]},{"id":"leg_kozhumiaka_992","kind":"legend","year":992,"place":"Переяслав","language":"old_east_slavic","title":"Кожум'яка","original":"и нарече и Переяславль, зане перея славу отрокъ тъ","translation":"…і назвав його Переяславом, бо перейняв славу той юнак.","fidelity":"plausible","sources":["PVL s.a. 6500 (992): the young tanner defeats the Pecheneg champion; folk etymology of Pereiaslav"]},{"id":"doc_ruska_pravda_1","kind":"document","year":1016,"place":"Київ","language":"old_east_slavic","title":"Руська Правда, стаття 1","original":"Убьеть мужь мужа, то мьстить брату брата, или сынови отца, любо отцю сына, или братучадо, любо сестрину сынови; аще ли не будеть кто мьстя, то 40 гривенъ за голову","translation":"Якщо вб'є муж мужа, то мстить брат за брата, або син за батька, або батько за сина, або небіж; якщо не буде месника, то 40 гривень за голову.","fidelity":"historical","sources":["Short Ruska Pravda, art. 1 (Academic copy of the Novgorod First Chronicle)"]},{"id":"doc_yaroslav_testament","kind":"document","year":1054,"place":"Київ","language":"old_east_slavic","title":"Заповіт Ярослава Мудрого","original":"Се азъ отхожю свѣта сего, сынове мои; имѣйте в собѣ любовь, понеже вы есте братья единого отца и матере","translation":"Ось я відходжу з цього світу, сини мої; майте між собою любов, бо ви брати від одного батька й однієї матері.","fidelity":"historical","sources":["PVL s.a. 6562 (1054)"]},{"id":"doc_liubech_1097","kind":"document","year":1097,"place":"Любеч","language":"old_east_slavic","title":"Любецький з'їзд","original":"Кождо да держить отчину свою","translation":"Хай кожен тримає свою отчину.","fidelity":"historical","sources":["PVL s.a. 6605 (1097), Liubech congress"]},{"id":"doc_yurii_1335","kind":"document","year":1335,"place":"Володимир","language":"latin","title":"Грамота Юрія II Болеслава","original":"Nos Georgius Dei gratia natus dux totius Russiae Minoris","translation":"Ми, Юрій, Божою милістю природжений князь усієї Малої Русі.","fidelity":"historical","sources":["Charter of Yurii II Boleslav to the Teutonic Order, Volodymyr, 1335 (EU: Little Rus')"]},{"id":"doc_lublin_1569","kind":"document","year":1569,"place":"Люблін","language":"polish","title":"Люблінська унія","original":"jest jedno nierozdzielne i nieróżne ciało, a także nieróżna, ale jedna spólna Rzeczpospolita","translation":"…є одне нероздільне й нерозрізнене тіло, і одна спільна Річ Посполита.","fidelity":"plausible","sources":["Act of the Union of Lublin, 1 July 1569 (Volumina Legum II; spelling modernised)"]},{"id":"doc_hadiach_1658","kind":"document","year":1658,"place":"Полтава","language":"polish","title":"Гадяцький договір","original":"Księstwo Ruskie","translation":"Князівство Руське — третій член Речі Посполитої поруч з Короною й Литвою (так і не набуло чинності).","fidelity":"plausible","sources":["Treaty of Hadiach, 16 September 1658 (Kyiv, Bracław and Chernihiv voivodeships as the Duchy of Ruthenia; EU: Hadiach, Treaty of)"]},{"id":"doc_orlyk_1710","kind":"document","year":1710,"place":"Бендери","language":"latin","title":"Конституція Пилипа Орлика","original":"Pacta et Constitutiones legum libertatumque Exercitus Zaporoviensis","translation":"Пакти й Конституції прав і вольностей Війська Запорозького.","fidelity":"historical","sources":["Latin version of the Bender constitution, 5 April 1710 (EU: Orlyk, Pylyp)"]},{"id":"doc_valuev_1863","kind":"document","year":1863,"place":"Київ","language":"russian","title":"Валуєвський циркуляр","original":"никакого особенного малороссийского языка не было, нет и быть не может","translation":"…жодної окремої малоросійської мови не було, немає і бути не може.","fidelity":"historical","sources":["Valuev Circular, 18 (30) July 1863 (EU: Valuev circular)"]},{"id":"doc_fourth_universal","kind":"document","year":1918,"place":"Київ","language":"ukrainian","title":"IV Універсал Центральної Ради","original":"Од нині Українська Народня Республіка стає самостійною, ні від кого незалежною, вільною, суверенною державою Українського Народу.","translation":"Віднині Українська Народна Республіка стає самостійною, ні від кого незалежною, вільною, суверенною державою українського народу.","fidelity":"historical","sources":["Fourth Universal of the Central Rada, 9 (22) January 1918"]},{"id":"doc_act_zluky","kind":"document","year":1919,"place":"Київ","language":"ukrainian","title":"Акт Злуки","original":"Однині воєдино зливаються століттями одірвані одна від одної частини єдиної України","translation":"Віднині воєдино зливаються століттями відірвані одна від одної частини єдиної України.","fidelity":"plausible","sources":["Universal of the Directorate on the unification (Act Zluky), 22 January 1919 (wording as in standard reprints)"]},{"id":"doc_independence_1991","kind":"document","year":1991,"place":"Київ","language":"ukrainian","title":"Акт проголошення незалежності України","original":"Верховна Рада Української РСР урочисто проголошує незалежність України та створення самостійної української держави — УКРАЇНИ.","translation":"Верховна Рада Української РСР урочисто проголошує незалежність України та створення самостійної української держави — УКРАЇНИ.","fidelity":"historical","sources":["Act of Declaration of Independence of Ukraine, 24 August 1991"]},{"id":"doc_constitution_1996","kind":"document","year":1996,"place":"Київ","language":"ukrainian","title":"Конституція України, стаття 1","original":"Україна є суверенна і незалежна, демократична, соціальна, правова держава.","translation":"Україна є суверенна і незалежна, демократична, соціальна, правова держава.","fidelity":"historical","sources":["Constitution of Ukraine, 28 June 1996, art. 1"]},{"id":"prov_bez_truda","kind":"proverb","year":null,"place":"","language":"ukrainian","title":"Прислів'я","original":"Без труда нема плода.","translation":"Без праці нема плоду.","fidelity":"plausible","sources":["Nomys M. (1864)"]},{"id":"prov_kozak_bida","kind":"proverb","year":null,"place":"","language":"ukrainian","title":"Прислів'я","original":"Козак з бідою, як риба з водою.","translation":"Козак з бідою, як риба з водою.","fidelity":"plausible","sources":["Nomys M. Ukrainski prykazky, pryslivia i take inshe (1864)"]},{"id":"prov_ne_tak","kind":"proverb","year":null,"place":"","language":"ukrainian","title":"Прислів'я","original":"Не так сталось, як гадалось.","translation":"Сталося не так, як гадалося.","fidelity":"plausible","sources":["Nomys M. (1864)"]},{"id":"prov_obre","kind":"proverb","year":null,"place":"","language":"old_east_slavic","title":"Прислів'я","original":"Погибоша аки обре","translation":"Загинули, як обри (про тих, хто зник безслідно).","fidelity":"historical","sources":["PVL, undated introduction: 'there is a saying in Rus' to this day: they perished like the Avars'"]}];
